package nexusfixture

import (
	"net/http"
	"regexp"
	"strconv"
	"strings"
)

// redacted is what replaces a credential or a secret value in a fixture.
const redacted = "<redacted>"

// Authorization values a fixture may carry: the scheme and nothing else.
const (
	authBasicRedacted  = "Basic " + redacted
	authBearerRedacted = "Bearer " + redacted
)

// ResponseHeaderAllowlist is the closed list of response headers a fixture
// keeps: everything else (Date, Set-Cookie, proxy and Nexus internals) is
// dropped by Redact and refused by CheckLeaks.
var ResponseHeaderAllowlist = []string{
	"Server", "Docker-Distribution-Api-Version", "WWW-Authenticate", "Location", "Link",
	"Docker-Content-Digest", "Content-Type", "Content-Length",
}

// requestHeaderAllowlist is what Redact keeps of a request, besides the
// normalized Authorization.
var requestHeaderAllowlist = []string{"Accept"}

// RawExchange is an exchange as the recorder read it from a Nexus: nothing is
// redacted yet, so it must never be written to a file as is.
type RawExchange struct {
	Method, Target, Host string
	RequestHeader        http.Header
	Status               int
	Header               http.Header
	Body                 []byte
}

// secretJSON matches a JSON member whose key names a secret: group 1 is the
// key and the colon, group 2 the value (a string, or a bare number or literal).
// Matching is textual so that a replaced body keeps every other byte as sent.
var secretJSON = regexp.MustCompile(
	`("(?:token|access_token|refresh_token|password|secret|uploaderIp)"\s*:\s*)("(?:[^"\\]|\\.)*"|[^\s,}\]"{\[]+)`)

var htmlTitle = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)

// Redact turns a raw exchange into one that is safe to write to a fixture: the
// Authorization value becomes a placeholder, request and response headers are
// filtered to their allowlists, an HTML body is summarized, an empty one is
// marked, and the values of the secret JSON keys are replaced in place. It does
// not modify raw.
func Redact(raw RawExchange) Exchange {
	ex := Exchange{
		Method: raw.Method, Target: raw.Target, Host: raw.Host,
		RequestHeader: redactRequestHeader(raw.RequestHeader),
		Status:        raw.Status,
		Header:        http.Header{},
	}
	for _, name := range ResponseHeaderAllowlist {
		if values := raw.Header.Values(name); len(values) > 0 {
			ex.Header[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
		}
	}
	switch {
	case len(raw.Body) == 0:
		ex.Stub = stubEmpty
	case isHTML(raw.Header, raw.Body):
		ex.Stub = htmlStub(raw.Body)
	default:
		ex.Body = []byte(redactSecretJSON(string(raw.Body)))
	}
	return ex
}

func redactRequestHeader(in http.Header) http.Header {
	out := http.Header{}
	if auth := in.Get("Authorization"); auth != "" {
		scheme, _, _ := strings.Cut(strings.TrimSpace(auth), " ")
		switch strings.ToLower(scheme) {
		case "basic":
			out.Set("Authorization", authBasicRedacted)
		case "bearer":
			out.Set("Authorization", authBearerRedacted)
		}
		// Any other scheme carries a secret we cannot place: the header is dropped.
	}
	for _, name := range requestHeaderAllowlist {
		if values := in.Values(name); len(values) > 0 {
			out[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
		}
	}
	return out
}

func isHTML(h http.Header, body []byte) bool {
	if strings.Contains(strings.ToLower(h.Get("Content-Type")), "text/html") {
		return true
	}
	head := strings.ToLower(strings.TrimSpace(string(body[:min(len(body), 64)])))
	return strings.HasPrefix(head, "<!doctype html") || strings.HasPrefix(head, "<html")
}

// htmlStub summarizes an HTML body as "<HTML body omitted: N bytes, <title>T</title>>"
// (the title is left out when there is none). The title is flattened to one
// line so that the stub stays one.
func htmlStub(body []byte) string {
	stub := stubHTMLStart + " " + strconv.Itoa(len(body)) + " bytes"
	if m := htmlTitle.FindSubmatch(body); m != nil {
		stub += ", <title>" + strings.Join(strings.Fields(string(m[1])), " ") + "</title>"
	}
	return stub + ">"
}

// redactSecretJSON replaces the value of each secret JSON key with "<redacted>".
// A null value is kept: it holds no secret.
func redactSecretJSON(body string) string {
	return secretJSON.ReplaceAllStringFunc(body, func(m string) string {
		sub := secretJSON.FindStringSubmatch(m)
		if sub[2] == "null" {
			return m
		}
		return sub[1] + `"` + redacted + `"`
	})
}
package nexusfixture

import (
	"net"
	"net/http"
	"net/netip"
	"regexp"
	"sort"
	"strings"
)

// Leak is one finding of CheckLeaks. It names where and which rule, never what
// matched: a field for the matched text would put a secret in a test log.
type Leak struct {
	Fixture string
	Line    int // 1-based
	Rule    string
}

// AllowedHosts are the only hosts a fixture may name, in a URL or a Host
// header: the loopback address the bench is published on and the bench's own
// proxy upstream (the one internal/nexusbench/testdata/descriptor.example.json
// names). The bench's LAN addresses are not allowed.
var AllowedHosts = []string{"127.0.0.1", "bench-upstream.nexus-bench.svc.cluster.local"}

// The rules, by the name a Leak carries.
const (
	ruleAuthorization  = "authorization-not-redacted"
	ruleSession        = "cookie-or-session"
	ruleHeaderAllowed  = "response-header-outside-allowlist"
	ruleJWT            = "jwt-like-value"
	ruleJSONSecret     = "REDACTED"
	ruleHost           = "host-not-allowed"
	rulePrivateAddress = "private-or-link-local-address"
	ruleInternalName   = "internal-name-or-path"
	ruleExactTerm      = "exact-term"
)

// sessionKV is the name of the Nexus session cookie, refused anywhere in a fixture.
const sessionKV = "NXSESSIONID"

var (
	jwtLike  = regexp.MustCompile(`eyJ[A-Za-z0-9_-]{10,}`)
	urlAuth  = regexp.MustCompile(`(?i)https?://([^\s/"'<>?#\\,;)]+)`)
	ipv4Like = regexp.MustCompile(`\b\d{1,3}(?:\.\d{1,3}){3}\b`)

	sessionHeaders = []string{"cookie", "set-cookie", "x-nexus-ui"}
	// internalNames are matched ignoring case; internalPaths exactly, because
	// "/users/" is a legitimate Nexus REST path.
	internalNames = []string{"datomir", "secrets.json", "xdg_state_home"}
	internalPaths = []string{"/home/", "/Users/"}
)

// lineState is where a line sits in the file: the commented header, or one of
// the parts of an exchange.
type lineState int

const (
	stMeta lineState = iota
	stReqLine
	stReqHeaders
	stRespLine
	stRespHeaders
	stBody
)

// CheckLeaks scans one fixture, line by line (lines count from 1), for what a
// fixture must not hold: an Authorization other than the placeholders, a cookie
// or session header, a response header outside ResponseHeaderAllowlist, a
// JWT-like value, a JSON secret key whose value is not "<redacted>", a host
// outside AllowedHosts, a private or link-local address, an internal name or
// local path, and each term of exact (recorder passwords and their Basic
// encodings, or an external deny list; an empty term matches nothing). The text
// is scanned as written, not parsed: a file that does not parse is still checked.
func CheckLeaks(fixture string, data []byte, exact []string) []Leak {
	c := &leakScan{fixture: fixture, seen: map[leakKey]bool{}}
	text := string(data)
	state := stMeta
	for i, line := range strings.Split(text, "\n") {
		state = c.scanLine(i+1, line, state, exact)
	}
	c.scanJSONSecrets(text)
	sort.SliceStable(c.leaks, func(i, j int) bool { return c.leaks[i].Line < c.leaks[j].Line })
	return c.leaks
}

type leakKey struct {
	line int
	rule string
}

type leakScan struct {
	fixture string
	leaks   []Leak
	seen    map[leakKey]bool
}

// add records a rule once per line.
func (c *leakScan) add(line int, rule string) {
	k := leakKey{line, rule}
	if c.seen[k] {
		return
	}
	c.seen[k] = true
	c.leaks = append(c.leaks, Leak{Fixture: c.fixture, Line: line, Rule: rule})
}

// scanLine checks one line and returns the state of the next.
func (c *leakScan) scanLine(n int, line string, state lineState, exact []string) lineState {
	if line == exchangeSep && state != stMeta {
		return stReqLine
	}
	if state == stReqHeaders || state == stRespHeaders {
		c.scanHeader(n, line, state)
	}
	c.scanText(n, line, exact)
	return nextState(state, line)
}

func nextState(state lineState, line string) lineState {
	switch state {
	case stMeta:
		if line == "" {
			return stReqLine
		}
	case stReqLine:
		return stReqHeaders
	case stReqHeaders:
		if line == "" {
			return stRespLine
		}
	case stRespLine:
		return stRespHeaders
	case stRespHeaders:
		if line == "" {
			return stBody
		}
	}
	return state
}

func (c *leakScan) scanHeader(n int, line string, state lineState) {
	name, value, ok := strings.Cut(line, ":")
	if !ok {
		return
	}
	name, value = strings.TrimSpace(name), strings.TrimSpace(value)
	lower := strings.ToLower(name)
	switch {
	case lower == "authorization" && value != authBasicRedacted && value != authBearerRedacted:
		c.add(n, ruleAuthorization)
	case contains(sessionHeaders, lower):
		c.add(n, ruleSession)
	}
	if state == stRespHeaders && !allowedResponseHeader(name) {
		c.add(n, ruleHeaderAllowed)
	}
	if state == stReqHeaders && lower == "host" && !allowedHost(value) {
		c.add(n, ruleHost)
	}
}

func allowedResponseHeader(name string) bool {
	canonical := http.CanonicalHeaderKey(name)
	for _, a := range ResponseHeaderAllowlist {
		if http.CanonicalHeaderKey(a) == canonical {
			return true
		}
	}
	return false
}

// scanText applies the rules that hold on any line, header or body.
func (c *leakScan) scanText(n int, line string, exact []string) {
	if strings.Contains(strings.ToUpper(line), sessionKV) {
		c.add(n, ruleSession)
	}
	if jwtLike.MatchString(line) {
		c.add(n, ruleJWT)
	}
	for _, m := range urlAuth.FindAllStringSubmatch(line, -1) {
		if !allowedAuthority(m[1]) {
			c.add(n, ruleHost)
		}
	}
	for _, ip := range ipv4Like.FindAllString(line, -1) {
		if addr, err := netip.ParseAddr(ip); err == nil && (addr.IsPrivate() || addr.IsLinkLocalUnicast()) {
			c.add(n, rulePrivateAddress)
		}
	}
	lower := strings.ToLower(line)
	for _, name := range internalNames {
		if strings.Contains(lower, name) {
			c.add(n, ruleInternalName)
		}
	}
	for _, p := range internalPaths {
		if strings.Contains(line, p) {
			c.add(n, ruleInternalName)
		}
	}
	for _, term := range exact {
		if term != "" && strings.Contains(line, term) {
			c.add(n, ruleExactTerm)
		}
	}
}

// scanJSONSecrets runs over the whole text, not line by line, because Redact
// replaces a secret value wherever it sits relative to its key. The leak is
// reported at the line of the key.
func (c *leakScan) scanJSONSecrets(text string) {
	for _, m := range secretJSON.FindAllStringSubmatchIndex(text, -1) {
		value := text[m[4]:m[5]]
		if value == `"`+redacted+`"` || value == "null" {
			continue
		}
		c.add(strings.Count(text[:m[0]], "\n")+1, ruleJSONSecret)
	}
}

// allowedAuthority checks the authority of a URL: no user info, and a host in
// AllowedHosts.
func allowedAuthority(authority string) bool {
	if strings.Contains(authority, "@") {
		return false
	}
	return allowedHost(authority)
}

// allowedHost checks a host with or without a port.
func allowedHost(hostPort string) bool {
	host := hostPort
	if h, _, err := net.SplitHostPort(hostPort); err == nil {
		host = h
	}
	host = strings.Trim(strings.ToLower(host), "[]")
	return contains(AllowedHosts, host)
}

