325	func itoa(n int) string {
326		var b [20]byte
327		i := len(b)
328		for {
329			i--
330			b[i] = byte('0' + n%10)
331			n /= 10
332			if n == 0 {
333				break
334			}
335		}
336		return string(b[i:])
337	}
