536	func TestCheckLeaksEachRuleCatchesItsLeak(t *testing.T) {
537		base := leakBase(t)
538		if leaks := nexusfixture.CheckLeaks(leakBaseName, []byte(base), nil); len(leaks) != 0 {
539			t.Fatalf("the unmodified base is not clean (%v): every case below would be meaningless", leaks)
540		}
541	
542		rules := map[string]bool{}
543		for _, tc := range leakCases() {
544			t.Run(tc.name, func(t *testing.T) {
545				data := plant(t, base, tc.old, tc.repl)
546				line := lineOf(data, tc.planted)
547				if line == 0 {
548					t.Fatalf("the planted value %q is not in the fixture: the case is broken", tc.planted)
549				}
550				leaks := nexusfixture.CheckLeaks("planted--admin", []byte(data), tc.exact)
551				if len(leaks) == 0 {
552					t.Fatalf("no leak reported for a planted %s:\n%s", tc.name, data)
553				}
554				for _, l := range leaks {
555					if l.Fixture != "planted--admin" {
556						t.Errorf("Leak.Fixture = %q, want the name given to CheckLeaks", l.Fixture)
557					}
558					if l.Rule == "" {
559						t.Errorf("a leak at line %d has no Rule", l.Line)
560					}
561					if l.Line != line {
562						t.Errorf("leak %q reported at line %d, want line %d (the only line that changed)", l.Rule, l.Line, line)
563					}
564					rules[l.Rule] = true
565				}
566				if echoed := fmt.Sprintf("%+v %#v", leaks, leaks); strings.Contains(echoed, tc.planted) {
567					t.Errorf("the leaks repeat the planted value: %s", echoed)
568				}
569			})
570		}
571		// The plan names nine rules (authorization, cookie/session, allowlist, JWT,
572		// JSON secret, host, private address, internal name, exact term): the cases
573		// above must not all be reported under fewer names.
574		if len(rules) < 9 {
575			t.Errorf("the planted leaks were reported under %d distinct Rule names (%v), want at least 9", len(rules), rules)
576		}
577	}
