642		if err != nil {
643			t.Fatal(err)
644		}
645		if len(files) == 0 || len(files) != len(all) {
646			t.Fatalf("%d fixture files on disk, %d embedded: the scan would not cover what the tests replay", len(files), len(all))
647		}
648	
649		exact := externalDenylist(t)
650		for _, file := range files {
651			data, err := os.ReadFile(file)
652			if err != nil {
653				t.Fatal(err)
654			}
655			name := strings.TrimSuffix(filepath.Base(file), ".http")
656			for _, l := range nexusfixture.CheckLeaks(name, data, exact) {
657				t.Errorf("%s line %d: leak, rule %q", file, l.Line, l.Rule)
658			}
659		}
660	
661		// The same files, as parsed and written back, say the same: Format is what
662		// the recorder writes.
663		for _, f := range all {
664			for _, l := range nexusfixture.CheckLeaks(f.Name, nexusfixture.Format(f), exact) {
665				t.Errorf("%s (formatted) line %d: leak, rule %q", f.Name, l.Line, l.Rule)
