670	// externalDenylist reads the optional deny list. It is never in the repository:
671	// its terms are the names of an instance that must not appear anywhere in it.
672	func externalDenylist(t *testing.T) []string {
673		t.Helper()
674		path := os.Getenv(denylistEnv)
675		if path == "" {
676			t.Logf("%s is not set: the external deny list was not used", denylistEnv)
677			return nil
678		}
679		data, err := os.ReadFile(path)
680		if err != nil {
681			t.Fatalf("%s names a file that cannot be read: %v", denylistEnv, err)
682		}
683		var terms []string
684		for line := range bytes.Lines(data) {
685			term := strings.TrimSpace(string(line))
686			if term != "" && !strings.HasPrefix(term, "#") {
687				terms = append(terms, term)
688			}
689		}
690		return terms
691	}
