// The scan stays linear in the size of the file: a body of about 1 MB made of
// 100,000 secret keys is reported whole in a few seconds, where counting the
// newlines before each match from the start of the file takes minutes. The
// bound is wide on purpose (a linear scan takes well under a second).
func TestCheckLeaksStaysLinearOnALargeBody(t *testing.T) {
	if testing.Short() {
		t.Skip("large input")
	}
	const keys = 100_000
	base := leakBase(t)
	o, r := bodyNote(strings.TrimSuffix(strings.Repeat("\\"token\\":1,\\n", keys), ",\\n"))
	data := []byte(plant(t, base, o, r))
	if len(data) < 900_000 {
		t.Fatalf("the input is %d bytes, want about 1 MB", len(data))
	}
	start := time.Now()
	leaks := nexusfixture.CheckLeaks("big--admin", data, nil)
	elapsed := time.Since(start)
	if len(leaks) != keys {
		t.Errorf("%d leaks reported, want one per secret key (%d)", len(leaks), keys)
	}
	if elapsed > 3*time.Second {
		t.Errorf("CheckLeaks took %s on %d bytes with %d secret keys, want a linear scan (under 3s)", elapsed, len(data), keys)
	}
}

